func _text(pos: Vector2, txt: String, sz: float, col: Color) -> void:
	draw_string(_f, pos + Vector2(1.5, 1.5), txt, HORIZONTAL_ALIGNMENT_LEFT, -1, sz, Color(0, 0, 0, 0.5))
	draw_string(_f, pos, txt, HORIZONTAL_ALIGNMENT_LEFT, -1, sz, col)

func _panel_rect() -> Rect2:
	var area := get_viewport().get_visible_rect().size
	return Rect2((area.x - PANEL_W) * 0.5, 70.0, PANEL_W, PANEL_H)

func feed(o: Dictionary) -> void:
	_gold = int(o.get("gold", 0))
	_hero_name = str(o.get("name", ""))
	var e = o.get("equip", [])
	_equip = (e.duplicate() if e is Array else [])
	_rec = str(o.get("rec", ""))
	queue_redraw()

func _rec_cost() -> int:
	if _rec == "":
		return 0
	var it: Dictionary = ItemDatabase.get_item(_rec)
	if it.is_empty():
		return 0
	var cost := int(it.get("cost", 0))
	for rid: String in it.get("requires", []):
		var idx := _equip.find(rid)
		if idx >= 0:
			cost -= int(ItemDatabase.get_item(rid).get("cost", 0))
	return maxi(cost, 0)

func _items_of_tab(t: int) -> Array:
	var out := []
	for id: String in ItemDatabase.items:
		var it: Dictionary = ItemDatabase.items[id]
		if _class_tab.get(str(it.get("class", "")), -1) == t:
			out.append(id)
	# 按 阶级(高→低) → 价格 排，让合成大件靠前
	out.sort_custom(func(a, b): return _sort_rank(a) < _sort_rank(b))
	return out

func _sort_rank(id: String) -> float:
	var it: Dictionary = ItemDatabase.items[id]
	return float(int(it.get("tier", 1)) * 10000) + float(int(it.get("cost", 0)))

func _slot_of(id: String) -> int:
	return _equip.find(id)

func _afford(id: String) -> bool:
	var it: Dictionary = ItemDatabase.items[id]
	var need := int(it.get("cost", 0))
	for rid: String in it.get("requires", []):
		var idx := _equip.find(rid)
		if idx >= 0:
			need -= int(ItemDatabase.items[rid].get("cost", 0))
	return _gold >= maxi(need, 0)
```

