		2: return Color(0.3, 0.7, 1.0)
		3: return Color(0.8, 0.48, 1.0)
		4: return Color(1.0, 0.78, 0.2)
		_: return Color(0.85, 0.85, 0.85)

func _tier_name(tier: int) -> String:
