	var e = o.get("equip", [])
	_equip = (e.duplicate() if e is Array else [])
	_rec = str(o.get("rec", ""))
	queue_redraw()

func _items_of_tab(t: int) -> Array:
	var out := []
	var ids = CATS.get(_tab_labels[clampi(t, 0, _tab_labels.size() - 1)], [])
	for id: String in ids:
		if not ItemDatabase.get_item(id).is_empty():
