			return cat
	return ""

func feed(o: Dictionary) -> void:
	_gold = int(o.get("gold", 0))
	var nm := str(o.get("name", ""))
	if nm != _hero_name:
		_hero_name = nm
		_plan_for = ""
	var e = o.get("equip", [])
	_equip = (e.duplicate() if e is Array else [])
