	_sep(dx, dx + dw - 8.0, y)
	y += 10.0
	_text(Vector2(dx, y + 15.0 * rs), "装备属性:", 15.0 * rs, Color.WHITE)
	y += 15.0 * rs + 10.0
	var fs_attr := 13.0 * rs
	for a in ATTR_ROWS:
