func _draw_header(panel: Rect2, rs: float) -> void:
	# host title Label：pos(20*rs, 10)，font 20*rs，Color.GOLD，outline 1
	var fs := 20.0 * rs
	_text(Vector2(panel.position.x + 20.0 * rs, panel.position.y + 10.0 + fs * 0.82), "商店  |  金币: %d" % _gold, fs, Color(1.0, 0.84, 0.0))

func _draw_close(panel: Rect2, rs: float) -> void:
	# host close_btn：锚右上，offset(-56, 6, -6, 56)，font 26*rs
	var r := Rect2(panel.position.x + PANEL_W - CLOSE_MARGIN - CLOSE_W, panel.position.y + CLOSE_MARGIN, CLOSE_W, CLOSE_W)
	_hot.append({"r": r, "k": "close", "a": 0})
	_box(r, Color(0.24, 0.27, 0.33, 0.95), Color(1, 1, 1, 0.22), 1, 5)
	var fs := 26.0 * rs
	_text_c(r.position.x + CLOSE_W * 0.5, r.position.y + CLOSE_W * 0.5 + fs * 0.36, "×", fs, Color(1, 1, 1, 0.92))

func _draw_tabs(panel: Rect2, rs: float) -> void:
	# host HBoxContainer：pos(20*rs, 45)，sep 6*rs，按钮 96*rs × 42*rs，font 14*rs
	var fs := 14.0 * rs
	var tw := 96.0 * rs
	var th := 42.0 * rs
	var gap := 6.0 * rs
	var x0 := panel.position.x + 20.0 * rs
	var y0 := panel.position.y + 45.0
	for i in range(_tab_labels.size()):
		var cat: String = _tab_labels[i]
		var r := Rect2(x0 + i * (tw + gap), y0, tw, th)
		_hot.append({"r": r, "k": "tab", "a": i})
		var tint: Color = _cat_style(cat)[1]
		var sel := i == _tab
		var bg := Color(0.18, 0.2, 0.26, 0.95) if sel else Color(0.05, 0.07, 0.11, 0.88)
		var bc := tint if sel else Color(1, 1, 1, 0.14)
		_box(r, bg, bc, 1, 9, 4 if sel else 0)
		var tc := Color(1.0, 0.92, 0.4) if sel else tint.lightened(0.55)
		_text_c(r.position.x + tw * 0.5, r.position.y + th * 0.5 + fs * 0.36, cat, fs, tc)

func _draw_grid(panel: Rect2, rs: float) -> void:
	# host ScrollContainer(anchor 0.02..0.56, top 110, bottom -34) + GridContainer 2 列
	var gx0 := panel.position.x + PANEL_W * GRID_L
	var gx1 := panel.position.x + PANEL_W * GRID_R
	var gy0 := panel.position.y + GRID_TOP
	var gy1 := panel.bottom + GRID_BOTTOM
	var list := _items_of_tab(_tab)
	if _sel == "" and not list.is_empty():
		_sel = str(list[0])
	var gap := 6.0 * rs
	var row_gap := 4.0 * rs
	var card_w := ((gx1 - gx0) - gap) * 0.5
	var rows_vis := maxi(1, int((gy1 - gy0 + row_gap) / (CARD_H + row_gap)))
	var max_scroll := maxi(0, ceili(float(list.size()) / 2.0) - rows_vis)
	_scroll = clampi(_scroll, 0, max_scroll)
	var start := _scroll * 2
	for n in range(start, mini(list.size(), start + rows_vis * 2)):
		var id: String = str(list[n])
		var col := (n - start) % 2
		var row := int((n - start) * 0.5)
		var r := Rect2(gx0 + col * (card_w + gap), gy0 + row * (CARD_H + row_gap), card_w, CARD_H)
		_draw_card(r, id, rs)

func _draw_card(r: Rect2, id: String, rs: float) -> void:
	_hot.append({"r": r, "k": "item", "a": id})
	var it: Dictionary = ItemDatabase.get_item(id)
	var tier := int(it.get("tier", 1))
	var tcol := _tier_color(tier)
	var owned := _slot_of(id) >= 0
	var can := _afford(id)
	var sel := id == _sel
	# host _item_card_style(tier, selected)
	var bg := Color(0.1, 0.12, 0.2, 0.96) if sel else Color(0.04, 0.06, 0.1, 0.9)
	var bc := tcol if sel else Color(tcol.r, tcol.g, tcol.b, 0.35)
	_box(r, bg, bc, 1, 8)
	var cs := _cat_style(_cat_of(id))
	_badge(r.position + Vector2(8.0, (CARD_H - BADGE) * 0.5), BADGE, str(cs[0]), cs[1], tcol, 26.0)
	# 名称 16*rs 白 + 价格 13*rs 金（host card 内 VBox，垂直居中）
	var fs_name := 16.0 * rs
	var fs_price := 13.0 * rs
	var lh_name := fs_name * 1.25
	var lh_price := fs_price * 1.25
	var top := r.position.y + (CARD_H - (lh_name + 3.0 + lh_price)) * 0.5
	var bx := r.position.x + 8.0 + BADGE + 12.0
	_text(Vector2(bx, top + fs_name * 0.95), str(it.get("name", id)), fs_name, Color.WHITE)
	var pc := Color(1.0, 0.82, 0.3) if (can or owned) else Color(1.0, 0.82, 0.3, 0.45)
	_text(Vector2(bx, top + lh_name + 3.0 + fs_price * 0.95), "%d 金币" % int(it.get("cost", 0)), fs_price, pc)
	# 右侧：品级 / 已拥有（host card 右侧 VBox）
	var fs_side := 12.0 * rs
	_text_r(r.position.x + r.size.x - 8.0, top + fs_side * 0.95, "[" + _tier_name(tier) + "]", fs_side, tcol)
	if owned:
		_text_r(r.position.x + r.size.x - 8.0, top + fs_side * 0.95 + fs_side * 1.35, "已拥有", fs_side, Color(0.45, 1.0, 0.5))

func _draw_owned(panel: Rect2, rs: float) -> void:
	# host shop_owned_container：贴底 30px 高，sep 4*rs，按钮 100×28
	var oy := panel.bottom - 30.0
	var x := panel.position.x + PANEL_W * GRID_L
	var x_end := panel.position.x + PANEL_W * GRID_R
	var gap := 4.0 * rs
	var fs := 14.0 * rs
	for s in range(_equip.size()):
		var w := 100.0
		if x + w > x_end:
			break
		var id := str(_equip[s])
		var it: Dictionary = ItemDatabase.get_item(id)
		var r := Rect2(x, oy + 1.0, w, 28.0)
		_hot.append({"r": r, "k": "owned", "a": s})
		var bc := Color(1.0, 0.84, 0.3, 0.85) if id == _sel else Color(1, 1, 1, 0.18)
		_box(r, Color(0.16, 0.19, 0.24, 0.95), bc, 1, 5)
		_text_c(r.position.x + w * 0.5, r.position.y + 14.0 + fs * 0.36, str(it.get("name", id)), fs, Color(1, 1, 1, 0.95))
		x += w + gap

func _draw_detail(panel: Rect2, rs: float) -> void:
	var it: Dictionary = ItemDatabase.get_item(_sel)
	if it.is_empty():
		return
	var dx := panel.position.x + PANEL_W * DETAIL_L
	var dw := PANEL_W * (DETAIL_R - DETAIL_L)
	var dy := panel.position.y + GRID_TOP
	var dby := panel.bottom + GRID_BOTTOM
	var tier := int(it.get("tier", 1))
	var tcol := _tier_color(tier)
	var cs := _cat_style(_cat_of(_sel))

	# 表头：76×76 类别徽章 + [品级] / 名称 24*rs / 总价 16*rs
	_badge(Vector2(dx, dy + 14.0), 76.0, str(cs[0]), cs[1], tcol, 36.0)
	var ix := dx + 92.0
	var fs13 := 13.0 * rs
	var fs24 := 24.0 * rs
	var fs16 := 16.0 * rs
	var y := dy + fs13
	_text(Vector2(ix, y), "[" + _tier_name(tier) + "]", fs13, tcol)
	y += fs24 + 4.0
	_text(Vector2(ix, y), str(it.get("name", _sel)), fs24, Color.WHITE)
	y += fs16 + 2.0
	_text(Vector2(ix, y), "总价 %d 金币" % int(it.get("cost", 0)), fs16, Color(1.0, 0.82, 0.3))
	y = maxf(y, dy + 14.0 + 76.0) + 16.0

	# 合成树 / 合成差价（host 同源 ItemDatabase API）
	if it.has("requires"):
		_text(Vector2(dx, y), "合成: " + ItemDatabase.get_synthesis_tree(_sel), 11.0 * rs, Color.GRAY)
		y += 11.0 * rs * 1.4 + 6.0
		if ItemDatabase.can_build(_sel, _equip):
			_text(Vector2(dx, y), "合成差价: %d金 (素材已拥有)" % ItemDatabase.get_synthesis_cost(_sel, _equip), 14.0 * rs, Color.GREEN)
			y += 14.0 * rs * 1.4 + 6.0

	# 装备属性（host numeric_attrs：橙色物理 / 紫色法术 / 浅绿其它）
	_sep(dx, dx + dw - 8.0, y)
	y += 10.0
	_text(Vector2(dx, y + 15.0 * rs), "装备属性:", 15.0 * rs, Color.WHITE)
	y += 15.0 * rs + 10.0
	var fs_attr := 13.0 * rs
	for a in ATTR_ROWS:
		var key := str(a[0])
		if it.has(key) and int(it[key]) != 0:
			var suffix := str(a[2]) if a.size() > 2 else ""
			var col := Color.LIGHT_GREEN
			if key in ["attack", "armor", "armor_pen_percent", "lifesteal", "crit_chance", "crit_damage"]:
				col = Color.ORANGE
			elif key in ["ability_power", "magic_resist", "magic_pen_percent", "spell_vamp", "per_ability_power"]:
				col = Color(0.7, 0.4, 1.0)
			_text(Vector2(dx, y), "  %s: +%d%s" % [str(a[1]), int(it[key]), suffix], fs_attr, col)
			y += fs_attr * 1.35 + 3.0

	# 被动 / 主动（黄色，超宽折行收进详情列宽）
	for pk in ["passive", "active"]:
		if it.has(pk):
			_sep(dx, dx + dw - 8.0, y)
			y += 10.0
			var lines := _wrap("[%s] %s" % [("被动" if pk == "passive" else "主动"), str(it[pk])], dw - 12.0, fs_attr)
			for ln: String in lines:
				_text(Vector2(dx, y + fs_attr), ln, fs_attr, Color.YELLOW)
				y += fs_attr * 1.35
			y += 4.0

	# 购买 / 出售（host：250×36 按钮 + 花费行 + 出售行）
	var slot := _slot_of(_sel)
	var owned := slot >= 0
	var can_more := not owned or tier < 3
	var actual := _need_cost(_sel)
	_sep(dx, dx + dw - 8.0, y)
	y += 12.0
	if can_more:
		var enabled := _gold >= actual and (_equip.size() < 6 or _has_component(_sel))
		var br := Rect2(dx, y, 250.0, 36.0)
		_button(br, "再买一件" if owned else "购买", enabled)
		if enabled:
			_hot.append({"r": br, "k": "buy", "a": _sel})
		y += 44.0
		var ptxt := "花费: %d金" % actual
		if _has_component(_sel):
			ptxt += " (合成)"
		if owned:
			ptxt += " [已拥有x1]"
		_text(Vector2(dx, y), ptxt, 12.0 * rs, Color.WHITE)
		y += 12.0 * rs + 10.0
	else:
		_button(Rect2(dx, y, 250.0, 36.0), "已拥有 (终极大件)", false)
		y += 44.0
	if owned:
		var sr := Rect2(dx, y, 250.0, 36.0)
		_button(sr, "出售 (70%%回收: %d金)" % int(int(it.get("cost", 0)) * 0.7), true, true)
		_hot.append({"r": sr, "k": "sell", "a": slot})
		y += 44.0

	# 总装备加成（host 用 hero.bonus_*；客户端按已购件属性累加）
	if y > dby - 40.0:
		return
	_sep(dx, dx + dw - 8.0, y)
	y += 10.0
	_text(Vector2(dx, y + 15.0 * rs), "── 总装备加成 ──", 15.0 * rs, Color.WHITE)
	y += 15.0 * rs + 10.0
	var tot := _bonus_totals()
	var fs_tot := 12.0 * rs
	for tr in TOTAL_ROWS:
		if y > dby - 24.0:
			break
		var k := str(tr[1])
		var val := float(tot.get(k, 0.0))
		if absf(val) < 0.01:
			continue
		var nm := str(tr[0])
		var tc := Color.LIGHT_GREEN
		if nm in ["攻击力", "护甲", "物穿", "物理吸血", "暴击率", "暴击伤害"]:
			tc = Color.ORANGE
		elif nm in ["法术强度", "魔抗", "法穿", "法术吸血"]:
			tc = Color(0.7, 0.4, 1.0)
		_text(Vector2(dx, y), "  %s: +%d" % [nm, int(round(val))], fs_tot, tc)
		y += fs_tot * 1.35 + 2.0

	# 联机补充：host 商店无推荐区（主界面推荐带另有 NetRecommendBar）；此处按 host 详情字号
	# 在详情列底部复刻 B 推荐 + 出装路线，数据来自 feed(rec) 与 ItemDatabase。
	var nxt := _rec
	if nxt == "":
		nxt = _plan_next(_plan())
	if nxt == "" or y > dby - 50.0:
		return
	_sep(dx, dx + dw - 8.0, y)
	y += 14.0
	_text(Vector2(dx, y + 13.0 * rs), "推荐出装：", 13.0 * rs, Color(1.0, 0.92, 0.4))
	y += 13.0 * rs * 1.6
	y = _draw_plan_line(dx, y, dw - 12.0, rs)
	var need := _need_cost(nxt)
	var rr := Rect2(dx, y, 430.0, 36.0)
	_hot.append({"r": rr, "k": "plannext", "a": nxt})
	var ok := _gold >= need
	_box(rr, Color(0.25, 0.4, 0.2, 0.95) if ok else Color(0.16, 0.17, 0.22, 0.95), Color(0.6, 1.0, 0.5, 0.9) if ok else Color(1, 1, 1, 0.18), 1, 6)
	var nm2 := str(ItemDatabase.get_item(nxt).get("name", nxt))
	var txt := "推荐: %s · %d金 · 点击购买 / B" % [nm2, need]
	_text_c(rr.position.x + rr.size.x * 0.5, rr.position.y + rr.size.y * 0.5 + 13.0 * rs * 0.36, txt, 13.0 * rs, Color(0.85, 1.0, 0.8) if ok else Color(1, 1, 1, 0.6))

# 出装路线一行（已购绿 / 下一件金 / 其余白，超宽折行）
func _draw_plan_line(x0: float, y0: float, max_w: float, rs: float) -> float:
	var plan := _plan()
	var fs := 12.0 * rs
	if plan.is_empty():
		_text(Vector2(x0, y0 + fs), "暂无推荐方案", fs, Color(1, 1, 1, 0.45))
		return y0 + fs * 1.6
	var nxt := _rec
	if nxt == "":
		nxt = _plan_next(plan)
	var x := x0
	var y := y0
	for i in range(plan.size()):
		var id := str(plan[i])
		var nm := str(ItemDatabase.get_item(id).get("name", id))
		var col := Color(1, 1, 1, 0.85)
		if _owned_n(id) > 0:
			col = Color(0.5, 1.0, 0.58)
		elif id == nxt:
			col = Color(1.0, 0.88, 0.38)
		var w := _f.get_string_size(nm, HORIZONTAL_ALIGNMENT_LEFT, -1, fs).x
		if x > x0 and x + w > x0 + max_w:
			x = x0
			y += fs * 1.4
		_text(Vector2(x, y + fs), nm, fs, col)
		x += w
		if i < plan.size() - 1:
			var arrow := " → "
			var aw := _f.get_string_size(arrow, HORIZONTAL_ALIGNMENT_LEFT, -1, fs).x
			if x > x0 and x + aw > x0 + max_w:
				x = x0
				y += fs * 1.4
			_text(Vector2(x, y + fs), arrow, fs, Color(1, 1, 1, 0.3))
			x += aw
	return y + fs * 1.8

