# ---------- 输入 ----------

func _unhandled_input(ev: InputEvent) -> void:
	if not (ev is InputEventKey and (ev as InputEventKey).pressed and not (ev as InputEventKey).echo):
		return
	match (ev as InputEventKey).keycode:
		KEY_O:
			toggle()
		KEY_B:
			if visible:
				quick_buy()
		KEY_ESCAPE:
			if visible:
				hide_panel()

func _gui_input(ev: InputEvent) -> void:
	var press := (ev is InputEventMouseButton and (ev as InputEventMouseButton).pressed and (ev as InputEventMouseButton).button_index == MOUSE_BUTTON_LEFT)
	if not press:
		return
	var p: Vector2 = (ev as InputEventMouseButton).position
	var panel := _panel_rect()
	# 右上 ✕ 或面板外 → 关闭
	if p.x >= panel.position.x + PANEL_W - 150.0 and p.y <= panel.position.y + 80.0:
		hide_panel()
		return
	if not panel.has_point(p):
		hide_panel()
		return
	var max_row := -1; var hit: Dictionary = {}
	for h in _hot:
		if (h["r"] as Rect2).has_point(p):
			var row := int((h["r"] as Rect2).position.y)
			if row >= max_row:
				max_row = row
				hit = h
	if hit.is_empty():
		return
	match str(hit["k"]):
		"tab":
			var nt: int = int(hit["a"])
			if nt != _tab:
				_tab = nt
				_scroll = 0
				queue_redraw()
		"item":
			var id: String = str(hit["a"])
			var s := _slot_of(id)
			if s >= 0:
				sell_slot(s)
			elif _afford(id):
				buy(id)
			queue_redraw()
		"sell":
			sell_slot(int(hit["a"]))
			queue_redraw()
		"rec":
			quick_buy()
		"plannext":
			# 出装路线「下一件」条：点它=按推荐推进（价格按需补差价，host 侧合成校验）
			var pn: String = str(hit["a"])
			if _gold >= _need_cost(pn):
				buy(pn)
			queue_redraw()

