{"command":"$probe = Join-Path $env:TEMP 'hk_shop_bs_probe.gd'; @'
extends SceneTree

func _initialize() -> void:
	await process_frame
	var vp := SubViewport.new()
	vp.size = Vector2i(2400, 1400)
	vp.render_target_update_mode = SubViewport.UPDATE_ALWAYS
	root.add_child(vp)
	var p = load("res://scripts/net/NetShopPanel.gd").new()
	vp.add_child(p)
	var own := {
		"gold": 5000, "name": "吕布", "equip": ["battle_axe", "resist_boots"], "rec": "sage_power",
		"bs": [["  攻击力: +120", Color.ORANGE], ["  生命值: +1100", Color.LIGHT_GREEN],
			["  暴击率: +25", Color.ORANGE], ["  法术强度: +80", Color(0.7, 0.4, 1.0)]],
	}
	p.feed(own)
	p.toggle()
	var f := 0
	while f < 60:
		await process_frame
		f += 1
	var kinds = {}
	for h in p._hot:
		kinds[h["k"]] = kinds.get(h["k"], 0) + 1
	print("FRAME60 hot=", p._hot.size(), " kinds=", kinds, " tabs=", p._tab_labels.size(), " sel=", p._sel)
	print("TAB_END=", 227.0 + 7 * (129.6 + 8.1) + 129.6)
	var own2 := own.duplicate(true)
	own2.erase("bs")
	p.feed(own2)
	f = 0
	while f < 10:
		await process_frame
		f += 1
	print("FALLBACK hot=", p._hot.size())
	var r := Rect2()
	for h in p._hot:
		if h["k"] == "tab" and int(h["a"]) == 7:
			r = h["r"]
	var ev := InputEventMouseButton.new()
	ev.button_index = MOUSE_BUTTON_LEFT
	ev.pressed = true
	ev.position = r.get_center()
	p._gui_input(ev)
	await process_frame
	await process_frame
	print("TAB7 tab=", p._tab, " items=", p._items_of_tab(7).size(), " sel=", p._sel, " rect=", r)
	print("PROBE_PASS")
	quit()
